#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> values = {2, 2, 3};
    map<int, int> frequency;
    set<int> distinct;

    for (int value : values) {
        ++frequency[value];
        distinct.insert(value);
    }

    for (auto [key, cnt] : frequency) {
        cout << key << ' ' << cnt << '\n';
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    priority_queue<int, vector<int>, greater<int>> pq;

    pq.push(5);
    pq.push(1);
    pq.push(4);

    while (!pq.empty()) {
        cout << pq.top() << ' ';
        pq.pop();
    }

    return 0;
}
